import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int n = (int) st.nval;

        long total = 0;
        int[] count = new int[1001]; // preços entre 1 e 1000 (counting sort)

        for (int i = 0; i < n; i++) {
            st.nextToken();
            int p = (int) st.nval;
            total += p;
            count[p]++;
        }

        long free = 0;
        int idx = 0; // posição na ordenação decrescente
        for (int p = 1000; p >= 1; p--) {
            int c = count[p];
            while (c-- > 0) {
                if (idx % 3 == 2) free += p; // barato de cada trio sai grátis
                idx++;
            }
        }

        System.out.println(total - free);
    }
}
